import os
base='/private/tmp/bench-scratch'
for name in sorted(os.listdir(base)):
    p=os.path.join(base,name)
    if not os.path.isdir(p):
        continue
    nfiles=0
    ndirs=0
    sample=None
    for root, dirs, files in os.walk(p):
        if 'node_modules' in root or '.next' in root:
            continue
        ndirs += 1
        for f in files:
            nfiles += 1
            if sample is None and f.endswith(('.ts','.tsx','.json','.md')):
                sample=os.path.join(root,f)
    print(f'{name}: files={nfiles} dirs~={ndirs} sample={sample}')
