input.new_string:
  const removed = await memberRepo.archiveMember(input.orgId, input.memberId);

  // The absence leaves with the member. Anyone they stood in for keeps the
  // window, but nothing may redirect to a user who is no longer here.
  await absenceRepo.deleteAbsence(input.orgId, removed.userId);
