}

/**
 * Marks `input.userId` away for a half-open window. Replaces any absence
 * already stored for that member in this workspace. Anyone who may change
 * roles may do this for any member; everyone else only for themselves.
 */
export async function setAbsence(
  actor: Actor,
  input: SetAbsenceInput,
): Promise<MemberAbsence> {
  assertOrgScope(actor, input.orgId);

  const member = await requireActiveMember(input.orgId, input.userId);
  assertCanEditAbsence(actor, member);

  const delegateUserId = input.delegateUserId ?? null;
  const note = input.note ?? null;
  assertWindow(input.startsAt, input.endsAt);
  assertDelegateIsOther(input.userId, delegateUserId);

  if (delegateUserId !== null) {
    await requireActiveMember(input.orgId, delegateUserId);
  }

  return absenceRepo.upsertAbsence({
    orgId: input.orgId,
    userId: input.userId,
    delegateUserId,
    startsAt: input.startsAt,
    endsAt: input.endsAt,
    note,
  });
}

/** Removes the absence. Doing so when none is stored is a no-op. */
export async function clearAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  assertOrgScope(actor, orgId);

  const member = await requireActiveMember(orgId, userId);
  assertCanEditAbsence(actor, member);

  await absenceRepo.deleteAbsence(orgId, userId);
}

/**
 * The stored absence while it has not ended, including a window that has not
 * started yet. `null` once it has ended or when none is set.
 */
export async function getAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<MemberAbsence | null> {
  assertOrgScope(actor, orgId);
  await requireActiveMember(orgId, userId);

  const stored = await absenceRepo.findAbsence(orgId, userId);
  if (!stored || absenceHasEnded(stored, new Date())) return null;
  return stored;
}

/** Active, non-removed members only. Anyone else is invisible to this API. */
async function requireActiveMember(orgId: OrgId, userId: UserId): Promise<Member> {
  const member = await memberRepo.findMember(orgId, userId);
  if (!member || member.status !== "active") {
    throw new NotFoundError("Member", userId);
  }
  return member;
}

/**
 * Own absence is every member's to set. Someone else's requires the same
 * permission as changing that member's role.
 */
function assertCanEditAbsence(actor: Actor, member: Member): void {
  if (actor.userId === member.userId) return;
  assertCan(actor, "member:update_role", memberResource(member));
}

function assertWindow(startsAt: IsoTimestamp, endsAt: IsoTimestamp): void {
  if (parseIso(endsAt).getTime() <= parseIso(startsAt).getTime()) {
    throw new Error("Absence end must be after the start");
  }
}

function assertDelegateIsOther(
  userId: UserId,
  delegateUserId: UserId | null,
): void {
  if (delegateUserId !== null && delegateUserId === userId) {
    throw new Error("A member cannot delegate their absence to themselves");
  }
}

