function windowAround(now = Date.now(), hours = 1) {
  return {
    startsAt: toIsoTimestamp(new Date(now - hours * 3600_000)),
    endsAt: toIsoTimestamp(new Date(now + hours * 3600_000)),
  };
}

async function away(
  tenant: Tenant,
  user: keyof Tenant["userIds"],
  delegate: keyof Tenant["userIds"] | null,
  range = windowAround(),
) {
  return memberService.setAbsence(tenant.actors[user], {
    orgId: tenant.org.id,
    userId: tenant.userIds[user],
    delegateUserId: delegate === null ? null : tenant.userIds[delegate],
    ...range,
    note: "out",
  });
}

