      memberService.setAbsence(tenant.actors.member, {
        orgId: tenant.org.id,
        userId: tenant.userIds.member,
        delegateUserId: tenant.userIds.member,
        ...range,
        note: null,
      }),
    ).rejects.toThrow(/themselves/);

    await expect(
      memberService.setAbsence(tenant.actors.member, {
        orgId: tenant.org.id,
        userId: tenant.userIds.member,
        delegateUserId: null,
        startsAt: range.endsAt,
        endsAt: range.startsAt,
        note: null,
      }),
    ).rejects.toThrow(/after the start/);

    await expect(
      memberService.setAbsence(tenant.actors.member, {
        orgId: tenant.org.id,
        userId: tenant.userIds.member,
        delegateUserId: null,
        startsAt: range.startsAt,
        endsAt: range.startsAt,
        note: null,
      }),
    ).rejects.toThrow(/after the start/);

    await expect(
      memberService.setAbsence(tenant.actors.member, {
        orgId: other.org.id,
        userId: tenant.userIds.member,
        delegateUserId: null,
        ...range,
        note: null,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      memberService.getAbsence(
        other.actors.owner,
        tenant.org.id,
        tenant.userIds.member,
      ),
