import { toIsoTimestamp } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { CommentId, OrgId, UserId } from "@/types/common";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

function windowAround(now = Date.now(), hours = 1) {
  return {
    startsAt: toIsoTimestamp(new Date(now - hours * 3600_000)),
    endsAt: toIsoTimestamp(new Date(now + hours * 3600_000)),
  };
}

async function away(
  tenant: Tenant,
  user: keyof Tenant["userIds"],
  delegate: keyof Tenant["userIds"] | null,
  range = windowAround(),
) {
  return memberService.setAbsence(tenant.actors[user], {
    orgId: tenant.org.id,
    userId: tenant.userIds[user],
    delegateUserId: delegate === null ? null : tenant.userIds[delegate],
    ...range,
    note: "out",
  });
}

describe("absence", () => {
  it("schema defaults", () => {
    const parsed = setAbsenceSchema.parse({
      orgId: "01HZZZZZZZZZZZZZZZZZZZZZZZ",
      userId: "01HYYYYYYYYYYYYYYYYYYYYYYY",
      startsAt: "2026-01-01T00:00:00.000Z",
      endsAt: "2026-01-02T00:00:00.000Z",
    });
    expect(parsed.delegateUserId).toBeNull();
    expect(parsed.note).toBeNull();
  });

  it("covers the product rules", async () => {
    const tenant = await createTenant("absence-rules", "growth");
    const other = await createTenant("absence-other", "growth");
    const range = windowAround();

    const stored = await away(tenant, "member", "admin", range);
    expect(stored).toEqual({
      orgId: tenant.org.id,
      userId: tenant.userIds.member,
      delegateUserId: tenant.userIds.admin,
      startsAt: range.startsAt,
      endsAt: range.endsAt,
      note: "out",
    });

    const again = await memberService.setAbsence(tenant.actors.owner, {
      orgId: tenant.org.id,
      userId: tenant.userIds.member,
      delegateUserId: tenant.userIds.viewer,
      ...range,
      note: "replaced",
    });
    expect(again.delegateUserId).toBe(tenant.userIds.viewer);
    expect(again.note).toBe("replaced");

    // put the delegate back to admin for the rest
    await away(tenant, "member", "admin", range);

    const future = windowAround(Date.now() + 5 * 24 * 3600_000);
    await memberService.setAbsence(tenant.actors.viewer, {
      orgId: tenant.org.id,
      userId: tenant.userIds.viewer,
      delegateUserId: tenant.userIds.admin,
      ...future,
      note: null,
    });
    const scheduled = await memberService.getAbsence(
      tenant.actors.member,
      tenant.org.id,
      tenant.userIds.viewer,
    );
    expect(scheduled?.startsAt).toBe(future.startsAt);

    const past = {
      startsAt: toIsoTimestamp(new Date(Date.now() - 2 * 3600_000)),
      endsAt: toIsoTimestamp(new Date(Date.now() - 3600_000)),
    };
    // can't set a past window that has ended if end is before start... this window is valid historically
    await memberService.setAbsence(tenant.actors.owner, {
      orgId: tenant.org.id,
      userId: tenant.userIds.owner,
      delegateUserId: null,
      ...past,
      note: null,
    });
    expect(
      await memberService.getAbsence(
        tenant.actors.admin,
        tenant.org.id,
        tenant.userIds.owner,
      ),
    ).toBeNull();

    await expect(
      memberService.setAbsence(tenant.actors.member, {
        orgId: tenant.org.id,
        userId: tenant.userIds.member,
        delegateUserId: tenant.userIds.member,
        ...range,
        note: null,
      }),
    ).rejects.toThrow(/themselves/);

    await expect(
      memberService.setAbsence(tenant.actors.member, {
        orgId: tenant.org.id,
        userId: tenant.userIds.member,
        delegateUserId: null,
        startsAt: range.endsAt,
        endsAt: range.startsAt,
        note: null,
      }),
    ).rejects.toThrow(/after the start/);

    await expect(
      memberService.setAbsence(tenant.actors.member, {
        orgId: tenant.org.id,
        userId: tenant.userIds.member,
        delegateUserId: null,
        startsAt: range.startsAt,
        endsAt: range.startsAt,
        note: null,
      }),
    ).rejects.toThrow(/after the start/);

    await expect(
      memberService.setAbsence(tenant.actors.member, {
        orgId: other.org.id,
        userId: tenant.userIds.member,
        delegateUserId: null,
        ...range,
        note: null,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      memberService.getAbsence(
        other.actors.owner,
        tenant.org.id,
        tenant.userIds.member,
      ),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      memberService.clearAbsence(
        other.actors.owner,
        tenant.org.id,
        tenant.userIds.member,
      ),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      memberService.setAbsence(tenant.actors.member, {
        orgId: tenant.org.id,
        userId: tenant.userIds.admin,
        delegateUserId: null,
        ...range,
        note: null,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(
      memberService.getAbsence(
        tenant.actors.member,
        tenant.org.id,
        other.userIds.admin,
      ),
    ).rejects.toBeInstanceOf(NotFoundError);

    // member is away, delegate is viewer (set above to admin — reset to admin confirmed)
    const created = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Redirect create",
        assigneeId: tenant.userIds.member,
      }),
    );
    expect(created.assigneeId).toBe(tenant.userIds.admin);

    const selfTaken = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "I take it",
        assigneeId: tenant.userIds.member,
      }),
    );
    expect(selfTaken.assigneeId).toBe(tenant.userIds.member);

    const plain = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Assign later" }),
    );
    const reassigned = await issueService.assignIssue(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: plain.id,
      assigneeId: tenant.userIds.member,
    });
    expect(reassigned.assigneeId).toBe(tenant.userIds.admin);

    const selfAssign = await issueService.assignIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: selfTaken.id,
      assigneeId: tenant.userIds.member,
    });
    expect(selfAssign.assigneeId).toBe(tenant.userIds.member);

    // chain: admin is also away, delegate viewer. assigning to member stays with admin.
    await away(tenant, "admin", "viewer", range);
    const chained = await issueService.assignIssue(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: plain.id,
      assigneeId: tenant.userIds.member,
    });
    expect(chained.assigneeId).toBe(tenant.userIds.admin);

    // no delegate: owner has no current absence (past one returns null and is not away)
    const noDel = await issueService.assignIssue(tenant.actors.admin, {
      orgId: tenant.org.id,
      issueId: plain.id,
      assigneeId: tenant.userIds.owner,
    });
    expect(noDel.assigneeId).toBe(tenant.userIds.owner);

    // alerts for assignment
    const assignedNotes = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.admin,
      unreadOnly: false,
      kind: ["issue_assigned"],
      limit: 25,
      cursor: null,
    });
    const memberNotes = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.member,
      unreadOnly: false,
      kind: ["issue_assigned"],
      limit: 25,
      cursor: null,
    });
    expect(assignedNotes.items.length).toBeGreaterThan(0);
    expect(memberNotes.items).toHaveLength(0);

    // mention both member and their delegate once
    await emit("comment.created", {
      orgId: tenant.org.id,
      actorId: tenant.userIds.owner,
      occurredAt: toIsoTimestamp(new Date()),
      commentId: "01HCOMMENTMENTIONMENTION01" as CommentId,
      issueId: plain.id,
      mentionedUserIds: [tenant.userIds.member, tenant.userIds.admin],
    });

    const mentionMember = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.member,
      unreadOnly: false,
      kind: ["comment_mention"],
      limit: 25,
      cursor: null,
    });
    const mentionAdmin = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.admin,
      unreadOnly: false,
      kind: ["comment_mention"],
      limit: 25,
      cursor: null,
    });
    expect(mentionMember.items).toHaveLength(1);
    expect(mentionAdmin.items).toHaveLength(1);

    // overdue goes to admin (member's delegate), not member. issue currently assigned to owner.
    // reassign a fresh issue to member via repo so it stays member (already assigned issues stay)
    const stay = await issueRepo.insertIssue(
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Already mine",
        assigneeId: tenant.userIds.member,
        dueAt: toIsoTimestamp(new Date(Date.now() - 3600_000)),
      }),
      tenant.userIds.owner,
      99,
    );
    await emit("issue.overdue", {
      orgId: tenant.org.id,
      actorId: null,
      occurredAt: toIsoTimestamp(new Date()),
      issueId: stay.id,
      projectId: tenant.project.id,
      dueAt: stay.dueAt!,
      assigneeId: tenant.userIds.member,
    });
    const overdueAdmin = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.admin,
      unreadOnly: false,
      kind: ["issue_overdue"],
      limit: 25,
      cursor: null,
    });
    const overdueMember = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.member,
      unreadOnly: false,
      kind: ["issue_overdue"],
      limit: 25,
      cursor: null,
    });
    expect(overdueAdmin.items).toHaveLength(1);
    expect(overdueMember.items).toHaveLength(0);

    // removal drops absence and clears delegate pointers
    const memberRow = await (async () => {
      const { findMember } = await import("@/server/repositories/member-repository");
      return findMember(tenant.org.id, tenant.userIds.admin);
    })();
    if (!memberRow) throw new Error("missing");
    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: memberRow.id,
    });
    await expect(
      memberService.getAbsence(
        tenant.actors.owner,
        tenant.org.id,
        tenant.userIds.admin,
      ),
    ).rejects.toBeInstanceOf(NotFoundError);

    const still = await memberService.getAbsence(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.member,
    );
    expect(still?.delegateUserId).toBeNull();

    await memberService.clearAbsence(
      tenant.actors.member,
      tenant.org.id,
      tenant.userIds.member,
    );
    expect(
      await memberService.getAbsence(
        tenant.actors.owner,
        tenant.org.id,
        tenant.userIds.member,
      ),
    ).toBeNull();
    await memberService.clearAbsence(
      tenant.actors.member,
      tenant.org.id,
      tenant.userIds.member,
    );

    // other workspace unaffected: set there separately
    await away(other, "member", "admin", range);
    const otherAbsence = await memberService.getAbsence(
      other.actors.owner,
      other.org.id,
      other.userIds.member,
    );
    expect(otherAbsence?.delegateUserId).toBe(other.userIds.admin);

    void subscribe;
    void UserId;
    void OrgId;
  });
